const allItems = $input.all().map(i => i.json);
console.log('Total items en $input.all(): ' + allItems.length);

const allBlogs = allItems.filter(i => i.ID_BLOG && !('STATUS' in i));
const existingRows = allItems.filter(i => 'STATUS' in i);

console.log('Blogs: ' + allBlogs.length + ' | Pipeline rows: ' + existingRows.length);

if (allBlogs.length === 0) {
  console.log('STOP: sin blogs configurados.');
  return [];
}

const VALID_STATUSES = new Set(['PENDING', 'QUEUED', 'CONTENT_READY', 'READY']);
const validRows     = existingRows.filter(r => VALID_STATUSES.has(String(r.STATUS ?? '').toUpperCase().trim()));
const junkRows      = existingRows.filter(r => { const s = String(r.STATUS ?? '').toUpperCase().trim(); return s === 'FAILED' || s === 'LOCK_TIMEOUT' || s === 'ERROR' || s === 'CANCELLED'; });
const publishedRows = existingRows.filter(r => String(r.STATUS ?? '').toUpperCase().trim() === 'PUBLISHED');

console.log('Backlog útil: ' + validRows.length + ' | Publicados: ' + publishedRows.length + ' | Basura ignorada: ' + junkRows.length);

const existingTitles = new Set(validRows.filter(r => r.TEMA_ARTICULO).map(r => r.TEMA_ARTICULO.toLowerCase().trim()));
const validByBlog = {};
validRows.forEach(r => { const id = String(r.ID_BLOG || '').trim(); if (id) validByBlog[id] = (validByBlog[id] || 0) + 1; });

const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const HIGH_RPM = ['abogad','impuest','legal','segur','accidente','multa','bienes','hipotec','salud','médic','insurance','lawyer','tax','accident'];
const isHighRpm = (nicho) => HIGH_RPM.some(k => (nicho || '').toLowerCase().includes(k));

const PENDING_THRESHOLD = 1000;
const MAX_BLOGS_PER_RUN = 10;
const TITLES_PER_BLOG = 50;

const blogsNeedingTitles = allBlogs
  .filter(b => b.ID_BLOG && (validByBlog[b.ID_BLOG] || 0) < PENDING_THRESHOLD)
  .sort((a, b) => {
    const aRpm = isHighRpm(a.NICHO) ? 0 : 1;
    const bRpm = isHighRpm(b.NICHO) ? 0 : 1;
    if (aRpm !== bRpm) return aRpm - bRpm;
    return (validByBlog[a.ID_BLOG] || 0) - (validByBlog[b.ID_BLOG] || 0);
  })
  .slice(0, MAX_BLOGS_PER_RUN);

console.log('Blogs que necesitan títulos: ' + blogsNeedingTitles.length);
if (blogsNeedingTitles.length === 0) {
  console.log('STOP: todos los blogs tienen backlog >= ' + PENDING_THRESHOLD + '.');
  return [];
}

blogsNeedingTitles.forEach(b => console.log('  → ' + (b.SITIO_URL || b.ID_BLOG) + ' útil=' + (validByBlog[b.ID_BLOG] || 0)));

return blogsNeedingTitles.map(blog => ({
  json: {
    blogId: blog.ID_BLOG,
    sitioUrl: blog.SITIO_URL || '',
    nicho: blog.NICHO || 'general',
    idioma: blog.IDIOMA || 'es',
    bloggerId: blog.BLOGGER_ID || '',
    isHighRpm: isHighRpm(blog.NICHO),
    existingTitles: Array.from(existingTitles).slice(0, 50),
    titlesPerBlog: TITLES_PER_BLOG,
    dateStr,
    validBacklog: validByBlog[blog.ID_BLOG] || 0
  }
}));

// Construye el payload JSON completo para DeepSeek.
// Usamos un Code node porque n8n HTTP Request v4.2 serializa
// mal el body cuando contiene expresiones mezcladas con JSON anidado.
const blog = $input.item.json;

const systemPrompt = 'Eres un experto SEO con 15 años de experiencia en content marketing y monetización con Adsense y afiliados. Generas títulos de artículos únicos, específicos y con alto potencial de tráfico orgánico. Respondes SOLO con JSON válido, sin markdown, sin explicaciones.';

const existingStr = (blog.existingTitles || []).slice(0, 30).join(' | ');

const strategy = blog.isHighRpm
  ? 'ESTRATEGIA HIGH-RPM:\n- BUYER INTENT PURO: búsquedas urgentes con dinero (abogados, impuestos, seguros, accidentes)\n- Micronichos ULTRA específicos: ciudad/estado + situación + año (ej: "abogado accidente camión Dallas TX sin cobro adelantado", "apelar workers comp denegada California 2024")\n- FAQ alta conversión: ¿cuánto cuesta?, ¿cómo reclamar?, ¿qué pasa si?\n- 5 artículos PILAR definitivos (PRIORITY=1) + 45 clusters ultra específicos (PRIORITY=2)'
  : 'ESTRATEGIA AUTORIDAD + AFILIADOS:\n- 30% informativos profundos (guías completas)\n- 40% buyer intent suave (comparativas, mejores opciones, reviews)\n- 30% FAQ conversional (preguntas reales)\n- 3 artículos PILAR definitivos (PRIORITY=1) + 47 clusters específicos (PRIORITY=2)';

const userPrompt = 'Genera exactamente ' + blog.titlesPerBlog + ' títulos SEO únicos para:\nBlog: ' + (blog.sitioUrl || blog.nicho) + '\nNicho: ' + blog.nicho + '\nIdioma: ' + blog.idioma + '\nTipo: ' + (blog.isHighRpm ? 'HIGH-RPM Adsense' : 'Autoridad + Afiliados') + '\nBacklog útil actual: ' + blog.validBacklog + ' títulos\n\n' + strategy + '\n\nOBLIGATORIO:\n- Títulos escritos como experto humano nativo en ' + blog.idioma + '\n- Long-tail específico (4-8 palabras mínimo)\n- Sin repetir estos temas ya existentes: ' + existingStr + '\n\nResponde SOLO con este JSON (sin markdown, sin texto extra):\n{"titles": [{"title": "...", "keywords": "kw1, kw2, kw3", "priority": 1}]}';

const payload = {
  model: 'deepseek-chat',
  temperature: 0.8,
  max_tokens: 4000,
  stream: false,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ]
};

console.log('Payload construido para blog: ' + blog.blogId + ' nicho=' + blog.nicho);
console.log('user prompt length: ' + userPrompt.length + ' chars');

return [{ json: { ...blog, _payload: JSON.stringify(payload) } }];

// === PARSEAR TÍTULOS — DIAGNÓSTICO COMPLETO ===
// prev viene de Construir Payload DeepSeek (nodo directamente anterior al HTTP).
// NO usamos $('Preparar por Blog') para evitar item-pairing gaps.
const dsResponse = $input.item.json;
let prev;
try {
  prev = $('Construir Payload DeepSeek').item.json;
} catch(e) {
  // fallback por si el item pairing falla
  prev = { blogId: 'UNKNOWN', nicho: '?', idioma: 'es', validBacklog: 0, existingTitles: [], dateStr: new Date().toISOString().slice(0,10).replace(/-/g,'') };
  console.log('WARN: no pudo leer Construir Payload DeepSeek: ' + e.message);
}

// --- DIAGNÓSTICO RESPUESTA DEEPSEEK ---
console.log('=== DEEPSEEK RESPONSE DIAGNÓSTICO ===');
console.log('Blog: ' + prev.blogId + ' (' + prev.nicho + ')');
console.log('Response keys: ' + Object.keys(dsResponse).join(', '));
console.log('Full response (primeros 600 chars): ' + JSON.stringify(dsResponse).substring(0, 600));

// Error HTTP
if (dsResponse.error) {
  throw new Error('DeepSeek API error: ' + JSON.stringify(dsResponse.error));
}

// Sin choices
if (!dsResponse.choices || !Array.isArray(dsResponse.choices) || dsResponse.choices.length === 0) {
  throw new Error('DeepSeek sin choices. Respuesta completa: ' + JSON.stringify(dsResponse).substring(0, 500));
}

const choice = dsResponse.choices[0];
console.log('choice keys: ' + Object.keys(choice).join(', '));
console.log('finish_reason: ' + choice.finish_reason);

const rawContent = (choice.message && choice.message.content) ? choice.message.content : '';
console.log('rawContent length: ' + rawContent.length);
console.log('rawContent COMPLETO: ' + rawContent);

if (!rawContent || rawContent.trim().length === 0) {
  throw new Error('DeepSeek devolvió content vacío. finish_reason=' + choice.finish_reason);
}

// --- PARSEO JSON ---
let titlesData;
const attempts = [
  // 1. directo
  () => JSON.parse(rawContent.trim()),
  // 2. quitar markdown
  () => JSON.parse(rawContent.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```\s*$/i,'').trim()),
  // 3. extraer primer objeto JSON del texto
  () => { const m = rawContent.match(/\{[\s\S]*\}/); if (!m) throw new Error('no JSON encontrado'); return JSON.parse(m[0]); }
];
for (let i = 0; i < attempts.length; i++) {
  try { titlesData = attempts[i](); break; }
  catch(e) { console.log('parse attempt ' + (i+1) + ' failed: ' + e.message); }
}
if (!titlesData) {
  throw new Error('No se pudo parsear JSON de DeepSeek. rawContent: ' + rawContent.substring(0, 400));
}

console.log('titlesData keys: ' + Object.keys(titlesData).join(', '));

// Buscar el array de títulos en varias keys posibles
const titles = titlesData.titles || titlesData.results || titlesData.data || titlesData.articulos || [];
console.log('Títulos encontrados: ' + titles.length);
if (titles.length > 0) {
  console.log('Ejemplo título[0]: ' + JSON.stringify(titles[0]));
}

if (titles.length === 0) {
  throw new Error('DeepSeek retornó objeto sin títulos. Keys: ' + Object.keys(titlesData).join(', ') + ' | Raw: ' + rawContent.substring(0, 300));
}

// --- INSERCIÓN SIN FILTRO DE DUPLICADOS (diagnóstico) ---
// existingTitles se usa SOLO para log, no bloquea
const existingSet = new Set((prev.existingTitles || []).map(t => t.toLowerCase().trim()));
console.log('existingTitles en memoria: ' + existingSet.size);
const dateStr = prev.dateStr || new Date().toISOString().slice(0,10).replace(/-/g,'');
const blogId  = String(prev.blogId || 'BLOG');

const rows = [];
let skippedDups = 0;
for (const t of titles) {
  if (!t.title || String(t.title).trim().length < 5) { console.log('SKIP título vacío/corto: ' + JSON.stringify(t)); continue; }
  const titleLower = String(t.title).toLowerCase().trim();
  if (existingSet.has(titleLower)) { skippedDups++; continue; }
  // NO agregamos a existingSet — queremos todos los nuevos posibles
  const uid = 'TF' + dateStr + '-' + blogId.substring(0,6).replace(/[^a-z0-9]/gi,'') + '-' + Date.now().toString(36).slice(-4) + '-' + Math.random().toString(36).slice(2,5);
  rows.push({
    ID_UNICO: uid,
    STATUS: 'PENDING',
    LOCK: 'FALSE',
    ID_BLOG: blogId,
    KEYWORD: String(t.keywords || t.title.split(' ').slice(0,4).join(' ')),
    TEMA_ARTICULO: String(t.title),
    ID_PARENT_SILO: '',
    PRIORITY: String(t.priority || 2),
    RETRY_COUNT: '0'
  });
}

console.log('=== RESULTADO FINAL ===');
console.log('DeepSeek generó: ' + titles.length + ' títulos');
console.log('Skipped (duplicados exactos en memoria): ' + skippedDups);
console.log('Nuevos a insertar: ' + rows.length);
if (rows.length > 0) {
  console.log('Ejemplo row[0]: ' + JSON.stringify(rows[0]));
}

if (rows.length === 0) {
  // Log pero NO throw — lanzar error haría que n8n marque el blog como fallido
  console.log('WARN: 0 títulos nuevos. ¿existingTitles ('+existingSet.size+') está bloqueando todo? Revisar logs arriba.');
  return [];
}

return rows.map(r => ({ json: r }));

const allItems = $input.all().map(i => i.json);
const toArchive = allItems.filter(r => {
  const status = String(r.STATUS ?? '').toUpperCase().trim();
  const retry = parseInt(String(r.RETRY_COUNT || '0'), 10);
  return (status === 'FAILED' || status === 'LOCK_TIMEOUT') && retry > 2 && r.ID_UNICO;
});
if (toArchive.length === 0) {
  console.log('Limpieza: sin huérfanos para archivar.');
  return [];
}
console.log('Archivando ' + toArchive.length + ' registros FAILED/LOCK_TIMEOUT (RETRY > 2)');
return toArchive.map(r => ({ json: { ID_UNICO: r.ID_UNICO, STATUS: 'ARCHIVED' } }));
